"""Bounded exact square-root enclosure component; not a generic floating root finder."""
from fractions import Fraction


def sqrt_bracket(n, absolute_tolerance=Fraction(1, 1000000), max_iterations=64):
    """Enclose the nonnegative sqrt of a bounded nonnegative integer exactly.

    The tolerance bounds midpoint absolute error by half the returned bracket
    width. Exact rational arithmetic removes evaluation/rounding uncertainty
    only for this fixed polynomial. It is not a generic floating root finder.
    """
    if type(n) is not int or not 0 <= n <= 1000000:
        raise ValueError("expected integer n in 0..1000000, excluding bool")
    if type(absolute_tolerance) not in (int, Fraction):
        raise ValueError("expected exact int/Fraction tolerance")
    tolerance = Fraction(absolute_tolerance)
    if not 0 < tolerance <= 1 or max(abs(tolerance.numerator), tolerance.denominator) > 10**12:
        raise ValueError("expected tolerance in (0,1] with bounded exact representation")
    if type(max_iterations) is not int or not 0 <= max_iterations <= 128:
        raise ValueError("expected0..128iterations, excluding bool")
    lower, upper = Fraction(0), Fraction(max(1, n))

    def result(status, iterations):
        return {"status": status, "n": n, "lower": lower, "upper": upper,
                "estimate": (lower + upper)/2, "absolute_error_bound": (upper-lower)/2,
                "absolute_tolerance": tolerance, "iterations": iterations}

    if n in (0, 1):
        lower = upper = Fraction(n)
        return result("exact", 0)
    for iterations in range(max_iterations + 1):
        if (upper-lower)/2 <= tolerance:
            return result("bracket-tolerance", iterations)
        if iterations == max_iterations:
            return result("iteration-limit", iterations)
        midpoint = (lower + upper)/2
        square = midpoint*midpoint
        if square == n:
            lower = upper = midpoint
            return result("exact", iterations+1)
        if square < n:
            lower = midpoint
        else:
            upper = midpoint
    raise AssertionError("unreachable bounded-loop exit")


def encode_result(result):
    """JSON-safe exact rationals as canonical strings; do not round to floats."""
    return {key: str(value) if type(value) is Fraction else value
            for key, value in result.items()}


if __name__ == "__main__":
    import json
    for arguments in [(4, Fraction(1, 1000), 8), (2, Fraction(1, 8), 8), (2, Fraction(1, 1000), 1)]:
        print(json.dumps(encode_result(sqrt_bracket(*arguments)), sort_keys=True))

