from math import isqrt
checks = 0
for n in range(101):
    result = sqrt_bracket(n,Fraction(1,1000),64)
    lo,hi = result["lower"],result["upper"]
    assert 0 <= lo <= hi and lo*lo <= n <= hi*hi
    assert result["status"] in ("exact","bracket-tolerance")
    assert result["absolute_error_bound"] <= Fraction(1,1000)
    checks += 1
    oracle = isqrt(n)  # independent exact integer-square reference
    if oracle*oracle == n:
        assert lo <= oracle <= hi
        checks += 1
limited = sqrt_bracket(2,Fraction(1,1000),1)
assert limited["status"] == "iteration-limit"
assert limited["absolute_error_bound"] > limited["absolute_tolerance"]
checks += 1
print(checks)
print(limited["status"])
for invalid in (True,-1,1000001,2.0):
    try:
        sqrt_bracket(invalid)
    except ValueError:
        print("rejected")
